import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class LmdbStoreFlushReproductionTest {

	private static final int COMMIT_COUNT = 8;
	private static final int SEED_COUNT = 64;
	private static final IRI PREDICATE = SimpleValueFactory.getInstance().createIRI("urn:issue:6070:predicate");

	@Test
	void committedChangesReachBackingStoreDuringOverlappingSnapshotReaders(@TempDir Path dataDir) throws Exception {
		LmdbStore store = newStore(dataDir);
		SailRepository repository = new SailRepository(store);
		repository.init();

		SailDataset activeReader = null;
		try {
			SailSource snapshotSource = store.getSailStore().getExplicitSailSource();
			activeReader = commitWithContinuousReaderHandoffs(repository, snapshotSource);

			assertEquals(COMMIT_COUNT, countRepository(repository),
					"committed changes remain visible through the repository");
			assertEquals(COMMIT_COUNT, countBackingStore(store),
					"committed changes should reach LMDB while snapshot readers continue");
		} finally {
			if (activeReader != null) {
				activeReader.close();
			}
			repository.shutDown();
		}
	}

	@Test
	void committedChangesReachBackingStoreDuringOverlappingTupleQueryResults(@TempDir Path dataDir) throws Exception {
		LmdbStore store = newStore(dataDir);
		SailRepository repository = new SailRepository(store);
		repository.init();

		QueryReader activeReader = null;
		try {
			seedRepository(repository);
			assertEquals(SEED_COUNT, countBackingStore(store), "seed data is already persisted before readers start");
			activeReader = commitWithContinuousQueryHandoffs(repository);

			assertEquals(SEED_COUNT + COMMIT_COUNT, countRepository(repository),
					"all committed changes remain visible through the repository");
			assertEquals(SEED_COUNT + COMMIT_COUNT, countBackingStore(store),
					"committed changes should reach LMDB while tuple query results continue");
		} finally {
			if (activeReader != null) {
				activeReader.close();
			}
			repository.shutDown();
		}
	}

	@Test
	void closingFinalTupleQueryResultDrainsPendingChanges(@TempDir Path dataDir) throws Exception {
		LmdbStore store = newStore(dataDir);
		SailRepository repository = new SailRepository(store);
		repository.init();

		QueryReader activeReader = null;
		try {
			seedRepository(repository);
			activeReader = commitWithContinuousQueryHandoffs(repository);

			assertEquals(SEED_COUNT + COMMIT_COUNT, countRepository(repository),
					"all committed changes remain visible through the repository");
			activeReader.close();
			activeReader = null;
			assertEquals(SEED_COUNT + COMMIT_COUNT, countBackingStore(store),
					"closing the final tuple query result flushes pending changes to LMDB");
		} finally {
			if (activeReader != null) {
				activeReader.close();
			}
			repository.shutDown();
		}
	}

	@Test
	void closingFinalSnapshotReaderDrainsPendingChanges(@TempDir Path dataDir) throws Exception {
		LmdbStore store = newStore(dataDir);
		SailRepository repository = new SailRepository(store);
		repository.init();

		SailDataset activeReader = null;
		try {
			SailSource snapshotSource = store.getSailStore().getExplicitSailSource();
			activeReader = commitWithContinuousReaderHandoffs(repository, snapshotSource);

			assertEquals(COMMIT_COUNT, countRepository(repository),
					"committed changes remain visible through the repository");
			activeReader.close();
			activeReader = null;
			assertEquals(COMMIT_COUNT, countBackingStore(store),
					"the final reader close flushes pending changes to LMDB");
		} finally {
			if (activeReader != null) {
				activeReader.close();
			}
			repository.shutDown();
		}
	}

	private static LmdbStore newStore(Path dataDir) {
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,posc").setForceSync(true);
		return new LmdbStore(dataDir.toFile(), config);
	}

	private static SailDataset commitWithContinuousReaderHandoffs(SailRepository repository, SailSource source)
			throws Exception {
		SailDataset activeReader = source.dataset(IsolationLevels.SNAPSHOT_READ);
		try {
			for (int i = 0; i < COMMIT_COUNT; i++) {
				try (RepositoryConnection connection = repository.getConnection()) {
					connection.begin(IsolationLevels.SNAPSHOT_READ);
					connection.add(SimpleValueFactory.getInstance().createIRI("urn:issue:6070:subject:" + i), PREDICATE,
							SimpleValueFactory.getInstance().createLiteral(i));
					connection.commit();
				}

				SailDataset successor = source.dataset(IsolationLevels.SNAPSHOT_READ);
				SailDataset previousReader = activeReader;
				activeReader = successor;
				previousReader.close();
			}
			return activeReader;
		} catch (Exception | Error failure) {
			if (activeReader != null) {
				try {
					activeReader.close();
				} catch (Exception closeFailure) {
					failure.addSuppressed(closeFailure);
				}
			}
			throw failure;
		}
	}

	private static void seedRepository(SailRepository repository) {
		try (RepositoryConnection connection = repository.getConnection()) {
			connection.begin(IsolationLevels.SNAPSHOT_READ);
			for (int i = 0; i < SEED_COUNT; i++) {
				connection.add(SimpleValueFactory.getInstance().createIRI("urn:issue:6070:seed:" + i), PREDICATE,
						SimpleValueFactory.getInstance().createLiteral(i));
			}
			connection.commit();
		}
	}

	private static QueryReader commitWithContinuousQueryHandoffs(SailRepository repository) {
		QueryReader activeReader = openPublicQueryReader(repository);
		try {
			for (int i = 0; i < COMMIT_COUNT; i++) {
				try (RepositoryConnection connection = repository.getConnection()) {
					connection.begin(IsolationLevels.SNAPSHOT_READ);
					connection.add(SimpleValueFactory.getInstance().createIRI("urn:issue:6070:subject:" + i), PREDICATE,
							SimpleValueFactory.getInstance().createLiteral(i));
					connection.commit();
				}

				QueryReader successor = openPublicQueryReader(repository);
				QueryReader previousReader = activeReader;
				activeReader = successor;
				previousReader.close();
			}
			return activeReader;
		} catch (RuntimeException | Error failure) {
			try {
				activeReader.close();
			} catch (RuntimeException closeFailure) {
				failure.addSuppressed(closeFailure);
			}
			throw failure;
		}
	}

	private static QueryReader openPublicQueryReader(SailRepository repository) {
		RepositoryConnection connection = repository.getConnection();
		try {
			String query = "SELECT ?s WHERE { ?s <" + PREDICATE.stringValue() + "> ?o }";
			TupleQueryResult result = connection.prepareTupleQuery(query).evaluate();
			assertTrue(result.hasNext(), "the tuple query should return seed or committed statements");
			result.next();
			assertTrue(result.hasNext(), "the open tuple query result should remain unexhausted");
			return new QueryReader(connection, result);
		} catch (RuntimeException | Error failure) {
			connection.close();
			throw failure;
		}
	}

	private static long countRepository(SailRepository repository) {
		try (RepositoryConnection connection = repository.getConnection()) {
			return connection.size();
		}
	}

	private static long countBackingStore(LmdbStore store) throws Exception {
		try (SailDataset dataset = store.getBackingStore().getExplicitSailSource().dataset(IsolationLevels.NONE);
				CloseableIteration<? extends Statement> statements = dataset.getStatements(null, null, null)) {
			long count = 0;
			while (statements.hasNext()) {
				statements.next();
				count++;
			}
			return count;
		}
	}

	private static final class QueryReader {
		private final RepositoryConnection connection;
		private final TupleQueryResult result;

		private QueryReader(RepositoryConnection connection, TupleQueryResult result) {
			this.connection = connection;
			this.result = result;
		}

		private void close() {
			try {
				result.close();
			} finally {
				connection.close();
			}
		}
	}
}
